class MyHashMap {
    vector<int> data;
public:
    MyHashMap() {
        data.resize(1000001, -1);
    }

    void put(int key, int value) {
        data[key] = value;
    }

    int get(int key) {
        return data[key];
    }

    void remove(int key) {
        data[key] = -1;
    }
};
